const menu=document.querySelector('.menu'),nav=document.querySelector('.nav');if(menu&&nav){menu.addEventListener('click',()=>{const on=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(on))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}))}
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduce){const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.06});document.querySelectorAll('.section,.hero-copy,.page-lead').forEach(el=>{el.classList.add('reveal');io.observe(el)});let busy=false;function animate(){let max=document.documentElement.scrollHeight-innerHeight;let bar=document.querySelector('.progress');if(bar)bar.style.transform=`scaleX(${max>0?scrollY/max:0})`;let cover=document.querySelector('.cover-cast');if(cover&&innerWidth>900)cover.style.setProperty('--hero-drift',`${Math.min(72,scrollY*.06)}px`);busy=false}addEventListener('scroll',()=>{if(!busy){requestAnimationFrame(animate);busy=true}},{passive:true});animate()}
const list=document.getElementById('archive-results');if(list&&window.BLUXE_ARCHIVE){const search=document.getElementById('archive-search'),category=document.getElementById('archive-category'),count=document.getElementById('results-count');function render(){const q=search.value.toLowerCase().trim(),cat=category.value;const rows=window.BLUXE_ARCHIVE.filter(x=>(cat==='All'||x.category===cat)&&[x.title,x.summary,x.category,x.format].join(' ').toLowerCase().includes(q));list.innerHTML='';rows.forEach(item=>{const card=document.createElement('article');card.className='archive-item';const label=document.createElement('span');label.className='number';label.textContent=`${item.format} / ${item.category} / ${item.year}`;const h=document.createElement('h3');h.textContent=item.title;const p=document.createElement('p');p.textContent=item.summary;const a=document.createElement('a');a.href=item.url;a.textContent=item.format==='Vol. 07'?'Explore in the annual edition ↗':'Read article ↗';if(item.url.startsWith('http')){a.target='_blank';a.rel='noopener'}card.append(label,h,p,a);list.append(card)});count.textContent=`${rows.length} of ${window.BLUXE_ARCHIVE.length} entries`;if(!rows.length)list.innerHTML='<p class="archive-item">No entries match. Try another term or section.</p>'}search.addEventListener('input',render);category.addEventListener('change',render);render()}
const form=document.getElementById('proposal-form');if(form){form.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(form),formats=f.getAll('format');const message=`BLUXE CENTURY PARTNERSHIP ENQUIRY\n\nPartner type: ${f.get('type')}\nArea of interest: ${formats.join(', ')||'To discuss'}\nMarket or territory: ${f.get('market')||'To discuss'}\nObjective: ${f.get('objective')||'To discuss'}\n\nPlease contact me to discuss a tailored proposal.`;document.getElementById('proposal-output').textContent=message;const link=document.getElementById('proposal-email');link.href='mailto:info@bluxecentury.com?subject='+encodeURIComponent('Bluxe Century partnership proposal')+'&body='+encodeURIComponent(message);link.hidden=false;document.getElementById('proposal-status').textContent='Your enquiry outline is ready. Review it, then open your email app to send it.'});document.getElementById('copy-proposal').addEventListener('click',async()=>{const txt=document.getElementById('proposal-output').textContent;if(txt.includes('PARTNERSHIP ENQUIRY')){try{await navigator.clipboard.writeText(txt);document.getElementById('proposal-status').textContent='Outline copied.'}catch{document.getElementById('proposal-status').textContent='Copy unavailable here. Select the outline above to copy it.'}}})}
const mag=document.getElementById('magazine-stories');if(mag&&window.BLUXE_ARCHIVE){window.BLUXE_ARCHIVE.slice(0,17).forEach((x,i)=>{const row=document.createElement('article');row.className='story-row';const num=document.createElement('span');num.className='number';num.textContent=String(i+1).padStart(2,'0');const body=document.createElement('div');const meta=document.createElement('span');meta.className='micro';meta.textContent=x.category+' / VOL. 07';const h=document.createElement('h3');h.textContent=x.title;const p=document.createElement('p');p.textContent=x.summary;const a=document.createElement('a');a.href='https://bluxe-century-new.jaysam77.chatgpt.site/';a.target='_blank';a.rel='noopener';a.textContent='Open annual edition ↗';body.append(meta,h,p,a);row.append(num,body);mag.append(row)})}
